  L23_2.tooltip = [[
Pre-saturation changes the amount of saturation in the negative prior to conversion. By doing this step before conversion, we're able to analyze and balance the colors appropriately. (If you find you want to try a different level, just unconvert and then reconvert.)

Lower numbers mean LESS saturation and LESS color separation in the final conversion. If you plan on using a high-contrast tone profile (like 'ALL-HARD'), it's typically a good idea to go with a lower pre-saturation level to balance out the extra saturation created by the contrast.]]
  L21_2 = L21_2(L22_2, L23_2)
