        L2_3 = [[
VUESCAN/SILVERFAST DNG INSTRUCTIONS:
================================

This setting is only for 48bit RAW DNGs created with Vuescan or Silverfast.

1. Before converting, ensure that the 'Negative Lab' raw profile sets with no errors. If it doesn't, hit 'cancel' below and run 'File > Plugin-Extras > Update Vuescan/Silverfast DNGs' and follow instructions.

2. Use the white balance selector in LR to sample the film border (or 'Auto WB' if no film border visible or LR won't allow you to sample the border).

3. If necessary, adjust your crop or border buffer so any non-film elements are excluded from the analysis.

4. Click 'CONVERT NEGATIVES' above]]
        return L2_3
      elseif A0_3 == "cameraScan" then
        L2_3 = [[
DIGITAL CAMERA SCAN INSTRUCTIONS:
==============================

This setting is for RAW 'scans' from digital cameras.

1. Before converting, use the white balance selector in LR to sample off the film border (you can do this once per roll and sync across photos). If no film border is available, use 'Auto WB' setting in Lightroom.

2. If necessary, adjust your crop or border buffer so any non-film elements are excluded from the analysis.

3. Click 'CONVERT NEGATIVES' above]]
        return L2_3
      elseif A0_3 == "linearScan" then
        L2_3 = [[
TIFF SCAN INSTRUCTIONS:
====================

This setting is for 16bit RGB TIF scans from film scanners.

1) If your scan is at gamma 1.8 or gamma 2.2 (recommended), skip to step 2. If your scan is gamma 1.0, first run the TIF SCAN PREP utility (File > Plugin-Extras > TIF Scan Prep). Then continue with the new TIF it creates.

2. Do NOT white balance balance in LR. This will create color casts on TIFs.

3. If necessary, adjust your crop or border buffer so any non-film elements are excluded from the analysis.

4. Click 'CONVERT NEGATIVES' above]]
        return L2_3
      else
        L2_3 = ""
        return L2_3
      end
    end
    L2_3 = L6_1
    L2_3 = L2_3.kUnsupportedDirection
    return L2_3
  end
  
