  L69_2.tooltip = [[
The 'Tone Profile' sets the baseline tonal interpretation for your image. The 3 main categories are:

1. CINEMATIC
Cinematic Tone Profiles use a special logarithmic curve when interpreting the negative. They produce good details in the highlights and smooth, even tonality through mids and shadows. Great for cine films.

2. LAB
The Lab Tone Profiles act more like professional lab scanners, adding an auto-density adjustments and bolder contrast.

3. LINEAR
A flat, neutral starting profile for further adjustment, with no added contrast. 'Linear + Gamma' adds the gamma curve for standard B+W film paper. 'Linear + Deep' keeps the low-contrast look, but pulls down the shadows for added dimension.]]
