    local L0_3, L1_3, L2_3, L3_3, L4_3, L5_3, L6_3
    L0_3 = "Color Picker Instructions"
    L1_3 = MAC_ENV
    if L1_3 then
      L1_3 = [[
1. Click the eyedropper tool in Negative Lab Pro. The Apple color picker dialog will open

2. Click the eyedropper tool at the bottom of the Apple color picker dialog. Your mouse should change to be a zoomed in view of pixels

3. Click in a neutral grey area in your image. It should not be too bright or too dark.

4. You should see your image update and the white balance temp and tint values change in Negative Lab Pro.

5. If you're not happy with the result, you can go back to step 2 and try again on a different area, or you can adjust the outputed temp and tint values in Negative Lab Pro to refine.

NOTE: You will generally get the most accurate results if all other settings are reset to zero and the tone profile is set to 'linear.']]
      if L1_3 then
        goto lbl_9
      end
    end
    L1_3 = [[
IMPORTANT: On Windows, the color picker will only work if Graphics Acceleration is turned OFF. You can do this in Preferences > Performance

1. Click and hold as you DRAG from the color well over to the part of the image you want to sample (note that your cursor will not appear to change during this).

2. The picker will sample every 2 seconds while you continue to hold your mouse button down. Release your mouse when your done.

3. You should see your image update and the white balance temp and tint values change in Negative Lab Pro.

4. If you're not happy with the result, you can always reset the white balance by hitting the 'WB' text in Negative Lab Pro, and try again on a different area, or you can adjust the outputed temp and tint values.

NOTE: You will generally get the most accurate results if all other settings are reset to zero and the tone profile is set to 'linear.']]
    ::lbl_9::
    L2_3 = "info"
    L3_3 = L4_1
