  L75_2 = [[
These settings use enhanced Lookup Tables (LUTs) to make precise adjustments to the Hue, Saturation and Luminence (HSL) of your captures:

NATURAL
Produces more natural looking colors, particular blues, by reproducing the color-space of photographic paper.

Lab
Reproduces common nuances in color from lab scanners, including purer neutrals, more vibrant 'peach' tones in skin, and strong seperation between greens and yellows.

CRYSTAL
Reproduces the richness and color reproduction of Crystal Archive paper, with subtractive print color reproduction and intense shadows.

PAKON
Reproduces the bold colors, bold contrast, and extra pure neutrals of the legendary Pakon scanner.]]
  L74_2.tooltip = L75_2
  L75_2 = "HSL"
  L74_2.title = L75_2
  
